13→   var icon: String? = "",
14→   var command: String? = "",
15→   var tooltip: String? = "",
16→) {
17→    companion object {
18→        const val TAB_WIDTH = 26
19→        const val TAB_HEIGHT = 32
20→        const val MAX_TABS = 14 // 7 верх + 7 низ
21→    }
22→
23→    fun isValid(): Boolean = !icon.isNullOrBlank() && !command.isNullOrBlank()
24→
25→    fun isTopTab(): Boolean = index < 7
26→
27→    /**
28→     * Вычисляет позицию таба относительно GUI инвентаря.
29→     */
30→    fun getX(guiLeft: Int, guiWidth: Int): Int {
31→        return guiLeft + (index % 7) * 25 + guiWidth / 2 - 176 / 2
32→    }
33→
34→    fun getY(guiTop: Int, guiHeight: Int): Int {
35→        return if (isTopTab()) guiTop - 28 else guiTop + guiHeight - 4
36→    }
37→
38→    fun contains(mouseX: Double, mouseY: Double, guiLeft: Int, guiWidth: Int, guiTop: Int, guiHeight: Int): Boolean {
39→        val sx = getX(guiLeft, guiWidth)
40→        val sy = getY(guiTop, guiHeight)
41→        return mouseX >= sx && mouseX < sx + TAB_WIDTH && mouseY >= sy && mouseY < sy + TAB_HEIGHT
42→    }
43→
44→    fun render(graphics: GuiGraphics, guiLeft: Int, guiWidth: Int, guiTop: Int, guiHeight: Int, hovered: Boolean) {
45→        val sx = getX(guiLeft, guiWidth)
46→        val sy = getY(guiTop, guiHeight)
47→
48→        // Фон таба
49→        val bgColor = if (hovered) 0xC0000000.toInt() else 0x80000000.toInt()
50→        graphics.fill(sx, sy, sx + TAB_WIDTH, sy + TAB_HEIGHT, bgColor)
51→
52→        // Рамка
53→        val borderColor = if (hovered) 0xFFDDDDDD.toInt() else 0xFFAAAAAA.toInt()
54→        graphics.fill(sx, sy, sx + TAB_WIDTH, sy + 1, borderColor)
55→        graphics.fill(sx, sy + TAB_HEIGHT - 1, sx + TAB_WIDTH, sy + TAB_HEIGHT, 0xFF555555.toInt())
56→        graphics.fill(sx, sy, sx + 1, sy + TAB_HEIGHT, borderColor)
57→        graphics.fill(sx + TAB_WIDTH - 1, sy, sx + TAB_WIDTH, sy + TAB_HEIGHT, 0xFF555555.toInt())
58→
59→        // Иконка по центру таба
60→        val item = getItem()
61→        val iconX = sx + (TAB_WIDTH - 16) / 2
62→        val iconY = sy + if (isTopTab()) 8 else 6
63→        graphics.renderItem(item, iconX, iconY)
64→    }
65→
66→    fun getItem(): ItemStack {
67→        val iconName = icon ?: return Items.AIR.defaultInstance
68→        return try {
69→            val location = if (iconName.contains(":")) {
70→                net.minecraft.resources.ResourceLocation.tryParse(iconName)
71→            } else {
72→                net.minecraft.resources.ResourceLocation.tryParse("minecraft:$iconName")
73→            } ?: return Items.AIR.defaultInstance
74→            val item = net.minecraft.core.registries.BuiltInRegistries.ITEM
75→                .getOptional(location)
76→                .orElse(null)
77→            item?.defaultInstance ?: Items.AIR.defaultInstance
78→        } catch (_: Exception) {
79→            Items.AIR.defaultInstance
80→        }
81→    }
82→}
